#!/usr/bin/env node
// npm run shoot -- regenerate screenshots/ and the share card.
//
//   node tools/shoot.mjs               against a dev server it starts itself
//   node tools/shoot.mjs --only=hero   one shot (names below)
//
// The counterpart to SIGNAL's tools/shoot.mjs, and here for SIGNAL's reason:
// a picture no tool owns is a picture that rots. SIGNAL's own og.jpg went
// stale exactly that way -- regenerated by hand, forgotten once, and the
// one image most people see first (the link preview) showed a header the
// app no longer had. So og.jpg here is DERIVED from the hero shot by the
// same run, never made by hand. Re-run this after changing any screen the
// README shows.
//
// It drives the real app through tools/lib/browser.mjs, with the same
// fakes as the smoke test (a stand-in YouTube player, canned lyrics and
// forecast): the pictures show the real UI with plausible content. Shots
// are taken at 2x for sharp README images. The share card needs ImageMagick
// (`magick` on PATH); without it the screenshots are still written and the
// card is skipped, loudly.

import { execFileSync } from 'node:child_process'
import { mkdirSync } from 'node:fs'
import { writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { Browser, openPage, freePort, sleep } from './lib/browser.mjs'

const args = Object.fromEntries(process.argv.slice(2).map((a) => a.replace(/^--/, '').split('=')).map(([k, v]) => [k, v ?? true]))
const here = path.dirname(fileURLToPath(import.meta.url))
const OUT = path.join(here, '..', 'screenshots')
const DESK = '#5E6B63'

async function grab(p, file, sel, margin = 24) {
  const clip = sel
    ? await p.ev(`(() => { const r = document.querySelector(${JSON.stringify(sel)}).getBoundingClientRect(); const m = ${margin}; return { x: Math.max(0, r.x - m), y: Math.max(0, r.y - m), width: Math.min(innerWidth, r.width + 2 * m), height: Math.min(innerHeight - Math.max(0, r.y - m), r.height + 2 * m), scale: 1 } })()`)
    : await p.ev(`({ x: 0, y: 0, width: innerWidth, height: innerHeight, scale: 1 })`)
  const { data } = await p.send('Page.captureScreenshot', { format: 'png', clip })
  await writeFile(path.join(OUT, file), Buffer.from(data, 'base64'))
  return file
}

const shots = {
  async hero(p, base) {
    await p.goto(`${base}?station=city-lights`)
    await p.key('p'); await sleep(4500)
    return grab(p, 'hero.png', '#tuner')
  },
  // No lyrics shot, on purpose: with the canned lyrics it shows "Line 4",
  // and with real ones it would commit someone's words into the repo.
  async guide(p, base) {
    await p.goto(`${base}?station=neon-stasis`)
    await p.key('p'); await sleep(1200)
    await p.key('g'); await sleep(400)
    await p.key('ArrowDown'); await p.key('ArrowDown'); await sleep(300)
    return grab(p, 'guide.png', '#guide .dialog')
  },
  async weather(p, base) {
    await p.browser.send('Browser.grantPermissions', { origin: new URL(base).origin, permissions: ['geolocation'], browserContextId: p.browserContextId })
    await p.goto(`${base}?station=after-hours`)
    await p.key('p'); await sleep(1200)
    await p.key('w'); await sleep(300); await p.key('Enter'); await sleep(1800)
    return grab(p, 'weather.png', '#weather .dialog')
  },
  async screensaver(p, base) {
    await p.goto(`${base}?station=circuit-crush`)
    await p.key('p'); await sleep(1500)
    await p.key('v'); await sleep(3000)
    return grab(p, 'screensaver.png', null)
  },
  async phone(p, base) {
    await p.goto(`${base}?station=cipher`)
    await p.key('p'); await sleep(4000)
    return grab(p, 'phone.png', '#tuner', 12)
  },
}
const SIZES = { phone: { width: 390, height: 760, mobile: true, touch: true, scale: 2 }, screensaver: { width: 1100, height: 620, scale: 2 } }

function hasMagick() { try { execFileSync('magick', ['-version'], { stdio: 'ignore' }); return true } catch (e) { return false } }

/** The share card: the hero window on the desk, 1200x630 (the size social
 *  scrapers crop to), centred, never upscaled past its own pixels. */
function shareCard() {
  execFileSync('magick', [path.join(OUT, 'hero.png'), '-resize', '1100x560>', '-background', DESK, '-gravity', 'center', '-extent', '1200x630', '-quality', '88', path.join(OUT, 'og.jpg')])
}

mkdirSync(OUT, { recursive: true })
const only = args.only ? String(args.only).split(',') : null
let server = null
let base = args.url
if (!base) {
  const { createServer } = await import('./dev-server.mjs')
  const port = await freePort()
  server = createServer()
  await new Promise((r) => server.listen(port, '127.0.0.1', r))
  base = `http://127.0.0.1:${port}/signal-95/`
}
const browser = new Browser()
try {
  await browser.launch()
  for (const [name, fn] of Object.entries(shots)) {
    if (only && !only.includes(name) && !(name === 'hero' && only.includes('og'))) continue
    const p = await openPage(browser, SIZES[name] ?? { scale: 2 })
    try { console.log(`  ${await fn(p, base)}`) } catch (e) { console.log(`  FAILED ${name}: ${e.message}`); process.exitCode = 1 } finally { await p.close().catch(() => {}) }
  }
  if (!only || only.includes('hero') || only.includes('og')) {
    if (hasMagick()) { shareCard(); console.log('  og.jpg (from hero.png)') } else { console.log('  SKIPPED og.jpg: no `magick` on PATH -- the share card is now stale'); process.exitCode = 1 }
  }
} finally {
  browser.close()
  server?.close()
}
